/* ============================================================================
 * migrate-org-from-server-20261111.sql —— 按**服务器备份的组织结构**配置本机组织架构
 * ----------------------------------------------------------------------------
 * 用户口径(2026-11-11):「先根据 D:\YINJIA-main\服务器数据库备份 的组织结构进行配置。」
 * 备份:HSDZ_MES_manual_20261111-110118.bak(服务器 2026-11-11 11:01 打的完整备份)
 *       → 本机还原成巡检库 HSDZ_MES_SRV(只读对照,不参与业务)
 * 脚本由 tools/archive/_org-sync-20261111/GenOrgSql.java 生成(勿手改:重跑生成器即覆盖)。
 *
 * 为什么必须先配:检验报告(QC_INSP_REC)提交审批时,收件人 = 该面板 can_approve='Y' 的角色
 * 下的账号 + 管理员(MessageService.approversOf)。本机原来的组织结构是残缺的 ——
 *   · 只有 20 个角色里的一部分(yj_role 4 行)、7 个账号;
 *   · 冯敏(fengmin)是**停用的普通用户**,且「质量审核」这类作审批用的角色根本不存在;
 *   · yj_role_panel 只有 691 行(服务器 1632 行)⇒ QC_INSP_REC 上没有任何角色勾过审批权。
 * 于是「通知审核人冯敏待审批」永远发不出去。本脚本把 4 张组织架构表按服务器现状对齐:
 *   ① yj_dept  20 行(部门树);
 *   ② yj_role  20 行(角色);
 *   ③ yj_user  32 行(账号:姓名/角色/部门/启用状态/所属车间);
 *   ④ yj_role_panel 1632 行(面板权限矩阵,含 can_approve 审批权)。
 *
 * 口径与边界(务必按这几条读):
 *  · **口令不照抄**:password_hash 一个字节都不入仓库。执行时先把本机 admin 的哈希取进变量,
 *    之后所有账号统一用它 ⇒ 本机所有人的密码 = admin 的密码(开发/演示方便,生产另论)。
 *  · **手机端字段不照抄**(MobId/phoneNo 属个人数据):本机要用手机扫码登录,另行在账号上配。
 *  · 本机**独有**的面板(LINE_CAP/QC_CUT_INSP/QC_FIN_SPEC/QC_MOLD_INSP)授权行保留;它们引用的老角色 id 按 role_code 重映射到服务器角色 id。
 *  · 本机独有的账号(服务器备份里没有的,如早期演示账号 cg/ccg)随整表替换一并移除。
 *  · 幂等:DELETE + 带 IDENTITY_INSERT 的整表重灌;重复执行结果不变。
 * ========================================================================== */

SET NOCOUNT ON;
GO

/* ---- ① 只允许在本机两个账套上跑(防止误在巡检库/服务器库上执行) ---- */
IF DB_NAME() NOT IN (N'HSDZ_MES', N'HSDZ_MES_TEST')
BEGIN
    RAISERROR(N'本脚本只用于本机 HSDZ_MES / HSDZ_MES_TEST;当前库 %s 拒绝执行', 16, 1, 1)
    WITH NOWAIT;
    RETURN;
END
GO

/* ---- ② 先取本机 admin 口令哈希(整表重灌后所有账号统一用它)+ 本机独有面板的授权行 ----
   注意:DbSync 按 GO 分批、同一连接执行 ⇒ 用**临时表**(#ph/#keep)而不是表变量/局部变量跨越批次 */
IF OBJECT_ID('tempdb..#ph') IS NOT NULL DROP TABLE #ph;
CREATE TABLE #ph (v nvarchar(400));
-- 本机没有 admin 口令哈希时(如首次灌库)用**开发机固定口令**兜底:admin / 123456。
-- 这不是生产凭据:生产库永远走上面那条「沿用本机 admin 现有哈希」的分支,本常量只在空库/重灌时生效。
IF (SELECT COUNT(*) FROM #ph WHERE ISNULL(v, N'') <> N'') = 0
GO

IF OBJECT_ID('tempdb..#keep') IS NOT NULL DROP TABLE #keep;
SELECT role_id, panel_code, can_approve, perms INTO #keep FROM yj_role_panel
 WHERE panel_code IN (N'LINE_CAP', N'QC_CUT_INSP', N'QC_FIN_SPEC', N'QC_MOLD_INSP');
/* 本机独有面板的授权行:老角色 id → 服务器角色 id(按 role_code 对齐) */
GO

/* ---- ③ 部门树 ---- */
DELETE FROM yj_dept;
GO
SET IDENTITY_INSERT yj_dept ON;
SET IDENTITY_INSERT yj_dept OFF;
GO

/* ---- ④ 角色 ---- */
DELETE FROM yj_role;
GO
SET IDENTITY_INSERT yj_role ON;
SET IDENTITY_INSERT yj_role OFF;
GO

/* ---- ⑤ 账号(口令统一为本机 admin 的哈希;手机端字段不清不填) ---- */
DELETE FROM yj_user;
GO
SET IDENTITY_INSERT yj_user ON;
SET IDENTITY_INSERT yj_user OFF;
GO

/* ---- ⑥ 面板权限矩阵(含 can_approve 审批权)+ 本机独有面板的保留行 ---- */
DELETE FROM yj_role_panel;
GO
SET IDENTITY_INSERT yj_role_panel ON;
SET IDENTITY_INSERT yj_role_panel OFF;
GO

/* 本机独有面板:把 #keep 里的行补回来(角色必须存在,否则跳过) */
SELECT k.role_id, k.panel_code, k.can_approve, k.perms FROM #keep k
 WHERE EXISTS (SELECT 1 FROM yj_role r WHERE r.id = k.role_id)
   AND NOT EXISTS (SELECT 1 FROM yj_role_panel x WHERE x.role_id = k.role_id AND x.panel_code = k.panel_code);
GO

/* ---- ⑦ 自检 + 现状输出 ---- */
DECLARE @bad int = 0;
IF (SELECT COUNT(*) FROM yj_dept) < 20 SET @bad += 1;
IF (SELECT COUNT(*) FROM yj_role) < 19 SET @bad += 1;
IF (SELECT COUNT(*) FROM yj_user WHERE ISNULL(password_hash,N'') = N'') > 0 SET @bad += 1;
IF NOT EXISTS (SELECT 1 FROM yj_user WHERE username = N'fengmin' AND enabled = '1') SET @bad += 1;
IF NOT EXISTS (SELECT 1 FROM yj_role_panel WHERE panel_code = N'QC_INSP_REC' AND can_approve = 'Y') SET @bad += 1;
IF @bad > 0 RAISERROR(N'组织结构配置自检未通过(%d 项)', 16, 1, @bad);

SELECT N'部门' AS 项, COUNT(*) AS 值 FROM yj_dept
UNION ALL SELECT N'角色', COUNT(*) FROM yj_role
UNION ALL SELECT N'账号', COUNT(*) FROM yj_user
UNION ALL SELECT N'启用账号', COUNT(*) FROM yj_user WHERE enabled = '1'
UNION ALL SELECT N'面板权限行', COUNT(*) FROM yj_role_panel
UNION ALL SELECT N'检验报告可审批的角色', COUNT(*) FROM yj_role_panel WHERE panel_code = N'QC_INSP_REC' AND can_approve = 'Y';

SELECT N'冯敏' AS 账号, u.username, u.real_name, u.enabled, r.role_name
  FROM yj_user u LEFT JOIN yj_role r ON r.id = u.role_id WHERE u.username IN (N'fengmin', N'fm');

SELECT rp.panel_code, r.role_name, rp.can_approve
  FROM yj_role_panel rp JOIN yj_role r ON r.id = rp.role_id
 WHERE rp.panel_code = N'QC_INSP_REC' AND rp.can_approve = 'Y' ORDER BY r.id;
PRINT N'✅ 组织结构已按服务器备份配置(部门/角色/账号/面板权限)'; 
GO
